import { describe, expect, it } from 'vitest'
import payload from './bls.json'
import { buildSeedFoods } from '../germanStaples'
import { kcalFromMacros } from '../../lib/nutrition'

/**
 * Sanity checks on the bundled Bundeslebensmittelschlüssel extract.
 *
 * This data is generated by a build-time script from the Max Rubner-Institut's
 * published XLSX, so these tests guard the extraction, not the source.
 */

const cols: Record<string, number> = {}
;(payload.cols as string[]).forEach((c, i) => (cols[c] = i))
const rows = payload.rows as Array<Array<string | number | null>>
const num = (r: (typeof rows)[number], k: string) => {
  const v = r[cols[k]]
  return typeof v === 'number' ? v : undefined
}

describe('BLS bundle integrity', () => {
  it('carries the documented number of foods', () => {
    // MRI documents 7,140 foods in BLS 4.0.
    expect(rows.length).toBe(7140)
  })

  it('records its provenance so the CC BY attribution cannot be lost', () => {
    expect(payload.source).toMatch(/Max Rubner-Institut/)
    expect(payload.source).toMatch(/CC BY 4\.0/)
    expect(payload.doi).toBe('10.25826/Data20251217-134202-0')
  })

  it('has a code and at least one name on every row', () => {
    for (const r of rows) {
      expect(String(r[cols.code] ?? '')).not.toBe('')
      expect(String(r[cols.en] ?? '') || String(r[cols.de] ?? '')).not.toBe('')
    }
  })

  it('uses unique BLS codes', () => {
    const codes = new Set(rows.map((r) => r[cols.code]))
    expect(codes.size).toBe(rows.length)
  })

  it('contains no physically impossible entry', () => {
    for (const r of rows) {
      const p = num(r, 'protein') ?? 0
      const c = num(r, 'carbs') ?? 0
      const f = num(r, 'fat') ?? 0
      const kcal = num(r, 'kcal') ?? 0
      expect(p + c + f, String(r[cols.en])).toBeLessThanOrEqual(105)
      expect(kcal, String(r[cols.en])).toBeLessThanOrEqual(950)
      expect(Math.min(p, c, f), String(r[cols.en])).toBeGreaterThanOrEqual(0)
    }
  })

  it('reports energy consistent with the LMIV factors', () => {
    // BLS computes energy with the same Annex XIV factors this app uses, so
    // agreement here proves the carb basis was not misread on import.
    let checked = 0
    let agreed = 0
    for (const r of rows) {
      const kcal = num(r, 'kcal')
      const p = num(r, 'protein')
      const c = num(r, 'carbs')
      const f = num(r, 'fat')
      if (kcal == null || kcal < 30 || p == null || c == null || f == null) continue
      checked++
      const derived = kcalFromMacros({
        protein: p, carbs: c, fat: f,
        fiber: num(r, 'fiber'), alcohol: num(r, 'alcohol'), polyols: num(r, 'polyols'),
      })
      if (Math.abs(derived - kcal) / kcal < 0.1) agreed++
    }
    expect(checked).toBeGreaterThan(4000)
    // If the carb column were "total" rather than "available", every
    // fibre-bearing food would disagree and this would collapse.
    expect(agreed / checked).toBeGreaterThan(0.95)
  })

  it('classifies raw and cooked variants', () => {
    const states = rows.map((r) => r[cols.state])
    expect(states.filter((s) => s === 'raw').length).toBeGreaterThan(500)
    expect(states.filter((s) => s === 'cooked').length).toBeGreaterThan(1000)
  })

  it('shows cooked meat concentrating protein relative to raw', () => {
    const find = (needle: string) =>
      rows.find((r) => String(r[cols.en]).toLowerCase() === needle.toLowerCase())
    const raw = find('Chicken breast fillet, raw')
    const fried = find('Chicken breast fillet fried')
    expect(raw).toBeDefined()
    expect(fried).toBeDefined()
    // Cooking drives off water, so protein per 100 g must go up.
    expect(num(fried!, 'protein')!).toBeGreaterThan(num(raw!, 'protein')!)
  })
})

describe('BLS agrees with the hand-written staples', () => {
  // BLS uses its own food names, so these are matched by the BLS name and
  // compared against the value the bundled seed list carries for the same
  // food. Small differences are expected and fine — the two are independent
  // sources — but a large one would mean something was mis-parsed.
  it.each([
    ['Oat flakes', 372, 30],
    ['Olive oil', 884, 20],
    ['Chicken breast fillet, raw', 106, 10],
    ['Banana raw', 89, 15],
  ])('%s is close to the bundled seed value', (name, seedValue, tol) => {
    const hit = rows.find((r) => String(r[cols.en]).toLowerCase() === name.toLowerCase())
    expect(hit, `${name} not found in BLS`).toBeDefined()
    expect(Math.abs(num(hit!, 'kcal')! - seedValue)).toBeLessThanOrEqual(tol)
  })

  it('covers the generic foods Open Food Facts is worst at', () => {
    // OFF is a packaged-goods database; nobody scans a potato. These are
    // exactly the entries BLS exists to provide.
    for (const needle of ['potato', 'broccoli', 'lentil', 'chicken breast', 'salmon', 'rice']) {
      const found = rows.some((r) => String(r[cols.en]).toLowerCase().includes(needle))
      expect(found, `no BLS entry matching "${needle}"`).toBe(true)
    }
  })

  it('keeps the seed list small enough to stay a fast-path, not a duplicate DB', () => {
    expect(buildSeedFoods().length).toBeLessThan(200)
  })
})
